export function normalizeNigerianPhone(input) {
  if (typeof input !== 'string') return null;

  // Remove all non-digit characters except for the leading '+'
  input = input.replace(/[^+\d]/g, '');

  // Check for valid country code and format
  if (!input.startsWith('+234') && !input.startsWith('00234') && !input.startsWith('234')) return null;

  // Remove country code and trunk digit if present
  if (input.startsWith('+234')) input = input.slice(4);
  else if (input.startsWith('00234')) input = input.slice(5);
  else if (input.startsWith('234')) input = input.slice(3);

  // Remove leading '0' if present
  if (input.startsWith('0')) input = input.slice(1);

  // Validate national number format
  if (!/^[789][01]\d{8}$/.test(input)) return null;

  // Return E.164 format
  return `+234${input}`;
}

export function formatNigerianPhone(input) {
  if (typeof input !== 'string') return null;

  // Normalize the input first
  const normalized = normalizeNigerianPhone(input);
  if (!normalized) return null;

  // Extract national number
  const nationalNumber = normalized.slice(4);

  // Format the national number
  return `0${nationalNumber.slice(0, 4)} ${nationalNumber.slice(4, 7)} ${nationalNumber.slice(7)}`;
}
